// Portraits: the picture of a sage's own podcast episode (the owner's cover for it, mostly an illustration of the
// sage), cut to the sage's head and shoulders and served from this site (/portraits/), so a visitor's browser
// never asks Spotify for it. public/data-portraits.json is generated by scripts/build_portraits.py from the
// reviewed crops in data/portraits-review.json, keyed by sage id; never hand-edit it. Bundled at build time.
//
// This is the one way a component gets a portrait. A sage with no entry has none (a real photograph, a cover
// that is not him, a cover with text across it ...): show nothing and leave no gap.
import portraitData from '../public/data-portraits.json'
import type { Locale } from './types'

/**
 * What the picture is. Almost every portrait is an illustration (a drawing, painting, print or AI picture); the owner
 * approved the cover photographs of two sages (André Neher, the Rebbetzin Chaya Mushka Schneerson) for the site, and those
 * are `photo`. The kind picks the caption and the alt text: never show a photograph under the illustration caption.
 */
export type PortraitKind = 'illustration' | 'photo'

export interface PortraitEntry {
  /** The roster label this entry was made for; guards against ids drifting (tests/portraits.test.ts). */
  label: string
  /** The Spotify episode id the picture was cut from. */
  episode: string
  /** Pixel width of the large file (384); the small one is always 128. */
  w: number
  kind: PortraitKind
}

export interface Portrait {
  /** 384 x 384 webp: the sage's head and shoulders. */
  src: string
  /** 128 x 128 webp, for lists and small panels. */
  srcSm: string
  /** The Spotify episode id the picture was cut from. */
  episode: string
  /** `photo` only for the pictures the owner approved as photographs. Pass the whole portrait to `portraitCredit` / `portraitAlt`. */
  kind: PortraitKind
}

export const PORTRAIT_SIZE = 384
export const PORTRAIT_SIZE_SM = 128

const entries = portraitData as unknown as Record<string, PortraitEntry>
const has = (id: string) => Object.prototype.hasOwnProperty.call(entries, id)

/** The sage's portrait, or null: most places must render nothing at all for null. */
export function portraitOf(id: string): Portrait | null {
  if (!has(id)) return null
  return { src: `/portraits/${id}.webp`, srcSm: `/portraits/${id}.sm.webp`, episode: entries[id].episode, kind: entries[id].kind }
}

export function hasPortrait(id: string): boolean {
  return has(id)
}

/** Every entry, for the tests and for tools; components use portraitOf. */
export function portraitEntries(): Array<[string, PortraitEntry]> {
  return Object.entries(entries)
}

/**
 * The caption of a portrait: shown under (or beside) every portrait of 96 px and more, linking to the episode on the
 * sage's page, and as the `title` of the small ones. An illustration is mostly made with AI; a photo is the owner's cover.
 */
export const PORTRAIT_CREDIT: Record<PortraitKind, Record<Locale, string>> = {
  illustration: {
    he: 'איור מתוך פרק הפודקאסט',
    en: 'Illustration from the podcast episode',
    ru: 'Иллюстрация из выпуска подкаста',
  },
  photo: {
    he: 'תמונה מתוך פרק הפודקאסט',
    en: 'Picture from the podcast episode',
    ru: 'Изображение из выпуска подкаста',
  },
}

/** The caption for this portrait in the page's language. */
export function portraitCredit(portrait: Pick<Portrait, 'kind'>, locale: Locale): string {
  return PORTRAIT_CREDIT[portrait.kind][locale]
}

/** The `alt` of a portrait `<img>`, in the page's language: "איור: <name>" for an illustration, "תמונה: <name>" for a photo. */
export function portraitAlt(name: string, locale: Locale, portrait: Pick<Portrait, 'kind'>): string {
  const word = {
    illustration: { he: 'איור', en: 'Illustration', ru: 'Иллюстрация' },
    photo: { he: 'תמונה', en: 'Picture', ru: 'Изображение' },
  }[portrait.kind][locale]
  return `${word}: ${name}`
}

/** The episode section of a sage's page (`id="listen"`), from another page. On the sage page itself use `#listen`. */
export function portraitEpisodeHref(id: string, locale: Locale): string {
  return `/${locale}/sage/${id}#listen`
}
